UPDATE resolve_case SET stage = #{stage},
  proposal_id = NULL, hold_kind = NULL, hold_until = NULL,
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND stage <> #{stage}

UPDATE resolve_case SET proposal_id = #{proposalId}, proposed_at = #{now}, confirm_due_at = #{confirmDueAt}, confirm_alerted_at = NULL,
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND stage = 'OPEN' AND proposal_id IS NULL AND hold_kind IS NULL

UPDATE resolve_case SET hold_kind = NULL, hold_until = NULL, propose_due_at = #{proposeDueAt}, propose_alerted_at = NULL,
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND hold_kind IS NOT NULL

UPDATE resolve_case SET decision = #{decision}, decision_record_id = #{recordId}, result_option_id = #{optionId}, resolved_by = #{resolvedBy},
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND decision IS NULL

UPDATE resolve_case SET

    propose_alerted_at = #{now}
    confirm_alerted_at = #{now}
    dispute_alerted_at = #{now}
  , version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND

    propose_alerted_at IS NULL AND 
    confirm_alerted_at IS NULL AND 
    dispute_alerted_at IS NULL AND

